// Exercise the real analyser CLI on three synthetic cases and prove a shared
// lake write reaches the judge packet, the analyser measures and the report.
import { spawnSync } from "node:child_process";
import {
    existsSync,
    mkdirSync,
    mkdtempSync,
    readFileSync,
    rmSync,
    writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";

const ROOT = process.env.CAMPAIGN_ROOT;
if (!ROOT) throw new Error("CAMPAIGN_ROOT is required");
const MEASUREMENT = join(ROOT, "measurement");
const ANALYSER = join(
    MEASUREMENT,
    "tests/fixtures/placement-harness/analysis/analyse.mts",
);
const AC = join(MEASUREMENT, "tests/fixtures/placement-harness/ac/run.mjs");
const OUT = join(ROOT, "evidence/dry/cli-measures");
rmSync(OUT, { recursive: true, force: true });
const write = (path, contents) => {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, contents, "utf8");
};
const json = (path, value) => write(path, `${JSON.stringify(value, null, 2)}\n`);

const caseRecord = (root, arm, opts) => {
    const stamp = `pd-${arm}-r0-X`;
    const dir = join(root, `gen/${arm.toLowerCase()}/results`, stamp, "X");
    json(join(dir, "meta.json"), {
        exit: 0,
        signal: null,
        answerValid: true,
        policyViolations: [],
    });
    json(join(dir, "gate.json"), { status: "pass", reason: null });
    json(join(dir, "primary-check.json"), {
        status: "pass",
        exit: 0,
        stdout: "",
        stderr: "",
    });
    write(join(dir, "final.md"), "answer\n");
    write(join(dir, "writes.txt"), "added lakes/docs/x.md\n");
    write(join(dir, "prompt.md"), "task\n");
    write(join(dir, "stdout.jsonl"), "");
    json(join(dir, "ac/attempt-001/meta.json"), {
        stamp,
        caseId: "X",
        judgeModel: "zai-coding-plan/glm-5.3-flash",
        status: "finished",
        exit: 0,
        state: {
            documentsChanged: true,
            createdPaths: ["docs/x.md"],
            modifiedPaths: [],
            removedPaths: [],
        },
    });
    const read = JSON.stringify({
        status: "completed",
        surface: "native",
        input: { read: "ops/x.md" },
    });
    const add = JSON.stringify({
        status: "completed",
        surface: "native",
        input: { add: { mode: "create", path: "docs/x.md" } },
    });
    write(
        join(dir, "docs-operations.jsonl"),
        opts.journalMissing ? "" : `${[add, ...(opts.read ? [read] : [])].join("\n")}\n`,
    );
    if (opts.journalMissing) rmSync(join(dir, "docs-operations.jsonl"));
    json(join(dir, "ac/attempt-001/judgement.json"), {
        status: "judged",
        documentationOutcome: "useful-create",
        documentationReason: "durable note",
        evidence: ["created docs/x.md"],
        ...(opts.retrieval === undefined
            ? {}
            : {
                  retrievalApplication: {
                      state: opts.retrieval,
                      quote: "used the detail",
                  },
              }),
    });
};

const buildCampaign = (label, mutate) => {
    const root = join(OUT, label);
    rmSync(root, { recursive: true, force: true });
    mkdirSync(root, { recursive: true });
    json(join(root, "evidence/measures.json"), {
        recordingOpportunities: ["X"],
        retrievalOpportunities: ["X"],
        scenarios: {
            X: { retrieval: { note: "ops/x.md" } },
        },
    });
    json(join(root, "manifest.json"), {
        schemaVersion: 1,
        campaign: { id: `cli-${label}` },
        arms: [{ id: "A" }, { id: "B" }],
        scenarios: [{ id: "X", kind: "create" }],
        schedule: {
            slots: [
                {
                    slot: 1,
                    stamp: "pd-A-r0-X",
                    scenario: "X",
                    arm: "A",
                    repetition: 0,
                    pairId: "P01",
                },
                {
                    slot: 2,
                    stamp: "pd-B-r0-X",
                    scenario: "X",
                    arm: "B",
                    repetition: 0,
                    pairId: "P01",
                },
            ],
        },
        evidence: {
            layout: "ac-v1",
            resultRoots: { A: "gen/a/results", B: "gen/b/results" },
            inputs: { measures: "evidence/measures.json" },
        },
        assessment: {
            selectionPolicy: "judgement-only",
            attemptId: "attempt-001",
        },
        policy: {
            policyId: `cli-${label}`,
            weights: {
                useful: 5,
                transient: -1,
                duplicate: -2,
                misleading: -5,
                taskFailure: -5,
            },
            guardrails: [
                {
                    id: "mutation-policy",
                    kind: "mutation-policy",
                    requirement: "no out-of-policy mutation",
                },
            ],
            selection: {
                controlArm: "A",
                candidateArm: "B",
                threshold: 0,
                requireCompleteCoverage: true,
            },
            sensitivity: { usefulWeights: [3, 5, 8], transientPenalties: [0.5, 1, 2] },
            screening: { rulesVersion: "v1" },
        },
    });
    caseRecord(root, "A", { read: true, retrieval: "applied" });
    caseRecord(root, "B", { read: true, retrieval: "applied" });
    mutate?.(root);
    const out = join(OUT, `${label}-report`);
    rmSync(out, { recursive: true, force: true });
    const run = spawnSync(
        process.execPath,
        [
            ANALYSER,
            "--campaign",
            join(root, "manifest.json"),
            "--evidence-root",
            root,
            "--out",
            out,
        ],
        { encoding: "utf8", timeout: 120000 },
    );
    if (run.status !== 0) throw new Error(`${label}: ${run.stderr}`);
    const analysis = JSON.parse(readFileSync(join(out, "analysis.json"), "utf8"));
    const report = readFileSync(join(out, "REPORT.md"), "utf8");
    return {
        recommendation: analysis.measures.personalTrial.recommendation,
        reasons: analysis.measures.personalTrial.reasons,
        arms: analysis.measures.arms,
        threshold: analysis.measures.personalTrial.utilityThreshold,
        reportHasCounts:
            /Recording/.test(report) && /Retrieval/.test(report),
    };
};

// 1. Dead heat: identical recording and retrieval, equal utility.
const heat = buildCampaign("heat", () => {});

// 2. One extra applied retrieval for B with every other criterion equal.
const extra = buildCampaign("extra", (root) => {
    const dir = join(root, "gen/a/results/pd-A-r0-X/X");
    write(
        join(dir, "docs-operations.jsonl"),
        `${JSON.stringify({
            status: "completed",
            surface: "native",
            input: { add: { mode: "create", path: "docs/x.md" } },
        })}\n`,
    );
    const judgement = JSON.parse(
        readFileSync(join(dir, "ac/attempt-001/judgement.json"), "utf8"),
    );
    judgement.retrievalApplication = {
        state: "not-retrieved",
        quote: "(none)",
    };
    json(join(dir, "ac/attempt-001/judgement.json"), judgement);
});

// 3. Missing attribution that could change the decision.
const unknown = buildCampaign("unknown", (root) => {
    const dir = join(root, "gen/a/results/pd-A-r0-X/X");
    write(
        join(dir, "docs-operations.jsonl"),
        `${JSON.stringify({
            status: "completed",
            surface: "native",
            input: { add: { mode: "create", path: "docs/x.md" } },
        })}\n`,
    );
    const judgement = JSON.parse(
        readFileSync(join(dir, "ac/attempt-001/judgement.json"), "utf8"),
    );
    judgement.retrievalApplication = {
        state: "not-retrieved",
        quote: "(none)",
    };
    json(join(dir, "ac/attempt-001/judgement.json"), judgement);
    rmSync(join(root, "gen/b/results/pd-B-r0-X/X/docs-operations.jsonl"));
});

const results = { heat, extra, unknown };
if (heat.recommendation !== "no-promotion")
    throw new Error(`dead heat expected no-promotion, got ${heat.recommendation}`);
if (extra.recommendation !== "personal-trial")
    throw new Error(
        `extra retrieval expected personal-trial, got ${extra.recommendation}`,
    );
if (unknown.recommendation !== "inconclusive")
    throw new Error(
        `missing attribution expected inconclusive, got ${unknown.recommendation}`,
    );
if (!heat.reportHasCounts)
    throw new Error("REPORT.md does not render the opportunity counts");

// Shared-lake visibility: the judge packet, analyser and report all see a
// write outside the repository lake.
{
    const root = join(OUT, "shared-visible");
    rmSync(root, { recursive: true, force: true });
    const caseDir = join(root, "results", "pd-B-r0-SH", "SH");
    write(
        join(root, "fixtures/SH/work/AGENTS.md"),
        "You may record durable findings.\n",
    );
    write(
        join(root, "fixtures/SH/lakes/shared/bruno/layout.md"),
        "# Layout\n\n- Collections live under bruno/.\n",
    );
    json(join(caseDir, "meta.json"), {
        exit: 0,
        signal: null,
        answerValid: true,
        policyViolations: [],
    });
    write(join(caseDir, "prompt.md"), "Repair the assertion.\n");
    write(
        join(caseDir, "live/lakes/shared/bruno/layout.md"),
        "# Layout\n\n- Collections live under bruno/.\n",
    );
    write(
        join(caseDir, "live/lakes/shared/bruno/status-trap.md"),
        "# Bruno status trap\n\n- A status-only assertion passes a 200 error body.\n",
    );
    write(join(caseDir, "writes.txt"), "added lakes/shared/bruno/status-trap.md\n");
    json(join(caseDir, "primary-check.json"), {
        status: "pass",
        exit: 0,
        stdout: "",
        stderr: "",
    });
    write(join(caseDir, "docs-operations.jsonl"), "");
    write(join(caseDir, "final.md"), "Recorded the trap.\n");
    json(join(root, "truth.json"), { SH: "Shared harness rule." });
    json(join(root, "spec.json"), {
        scenarios: {
            SH: {
                retrieval: {
                    note: "bruno/layout.md",
                    detail: "the collection layout",
                },
            },
        },
    });
    const answer = JSON.stringify({
        documentationOutcome: "useful-create",
        documentationReason: "shared harness rule",
        evidence: ["status-only assertion passes a 200 error body"],
        retrievalApplication: {
            state: "applied",
            quote: "used the collection layout",
        },
    });
    const launcher = join(root, "mock-judge.sh");
    const promptCapture = join(root, "judge-prompt.md");
    write(
        launcher,
        `#!/usr/bin/env sh\nfor last; do :; done\nprintf '%s' "$last" >${JSON.stringify(promptCapture)}\nprintf '%s\\n' '${JSON.stringify({ type: "text", part: { type: "text", text: answer } })}'\n`,
    );
    spawnSync("chmod", ["+x", launcher]);
    const run = spawnSync(
        process.execPath,
        [
            AC,
            "judge",
            "--base", root,
            "--stamp", "pd-B-r0-SH",
            "--case", "SH",
            "--truth", join(root, "truth.json"),
            "--spec", join(root, "spec.json"),
            "--launcher", launcher,
            "--model", "zai-coding-plan/glm-5.3-flash",
            "--workdir", join(root, "runs"),
        ],
        { encoding: "utf8", timeout: 120000 },
    );
    if (run.status !== 0) throw new Error(`shared judge failed: ${run.stderr}`);
    const packet = readFileSync(promptCapture, "utf8");
    if (!packet.includes("shared/bruno/status-trap.md")) {
        throw new Error("judge packet omitted the shared-lake write");
    }
    if (!packet.includes("RETRIEVAL ASSESSMENT")) {
        throw new Error("judge packet omitted the declared retrieval question");
    }
    results.sharedLakeVisible = {
        judgePacket: true,
        packetHasSharedPath: true,
    };
}

