// Close the paid campaign at P04 without another model call: reconcile the
// ledger, write the billing view, and prepare arm-blinded human-review packets
// for the four retrieval opportunities whose judge input was never captured.
import { appendFileSync, existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { dirname, join } from "node:path";

const ROOT = process.env.CAMPAIGN_ROOT;
if (!ROOT) throw new Error("CAMPAIGN_ROOT is required");
const EVIDENCE = join(ROOT, "evidence");
const LEDGER = join(EVIDENCE, "ATTEMPTS.jsonl");
const schedule = JSON.parse(readFileSync(join(EVIDENCE, "schedule.json"), "utf8"));
const measurement = JSON.parse(
    readFileSync(join(EVIDENCE, "measurement-spec.json"), "utf8"),
);
const slots = schedule.slots;
const runSlots = slots.slice(0, 8);
const unrunSlots = slots.slice(8);
const readJson = (path) => JSON.parse(readFileSync(path, "utf8"));
const readText = (path) => (existsSync(path) ? readFileSync(path, "utf8") : "");
const write = (path, body) => {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, body, "utf8");
};
const sha = (text) => createHash("sha256").update(text, "utf8").digest("hex");
const ledger = (entry) =>
    appendFileSync(LEDGER, `${JSON.stringify({ at: new Date().toISOString(), ...entry })}\n`);

const caseDir = (slot) =>
    join(ROOT, "gen", slot.arm.toLowerCase(), "results", slot.stamp, slot.scenario);

// Token totals from one JSONL trail.
const usageOf = (path) => {
    const total = { input: 0, output: 0, reasoning: 0, cacheRead: 0, steps: 0 };
    for (const line of readText(path).split("\n")) {
        if (line.trim() === "") continue;
        let event;
        try {
            event = JSON.parse(line);
        } catch {
            continue;
        }
        if (event.type !== "step_finish" || !event.part?.tokens) continue;
        const tokens = event.part.tokens;
        total.steps += 1;
        total.input += tokens.input ?? 0;
        total.output += tokens.output ?? 0;
        total.reasoning += tokens.reasoning ?? 0;
        total.cacheRead += tokens.cache?.read ?? 0;
    }
    return total;
};

const trialUsage = { input: 0, output: 0, reasoning: 0, cacheRead: 0, steps: 0 };
const judgeUsage = { input: 0, output: 0, reasoning: 0, cacheRead: 0, steps: 0 };
const failedJudge = { attempts: 0, steps: 0, input: 0, output: 0 };
let successfulJudgements = 0;

for (const slot of runSlots) {
    const dir = caseDir(slot);
    const trial = usageOf(join(dir, "stdout.jsonl"));
    for (const key of Object.keys(trialUsage)) trialUsage[key] += trial[key];
    const failed = usageOf(join(dir, "ac/attempt-001/output.jsonl"));
    failedJudge.attempts += 1;
    failedJudge.steps += failed.steps;
    failedJudge.input += failed.input;
    failedJudge.output += failed.output;
    const judged = readJson(join(dir, "ac/attempt-002/judgement.json"));
    if (judged.status === "judged") successfulJudgements += 1;
    const recovery = usageOf(join(dir, "ac/attempt-002/output.jsonl"));
    for (const key of Object.keys(judgeUsage)) judgeUsage[key] += recovery[key];
}

const rate = (tokens, usdPerMillion) => (tokens / 1_000_000) * usdPerMillion;
const trialEstimate =
    rate(trialUsage.input, 0.15) +
    rate(trialUsage.output + trialUsage.reasoning, 0.6) +
    rate(trialUsage.cacheRead, 0.003);
const judgeEstimate =
    rate(judgeUsage.input, 0.0334) +
    rate(judgeUsage.output + judgeUsage.reasoning, 0.1163) +
    rate(judgeUsage.cacheRead, 0.0081);

const reconciliation = {
    at: new Date().toISOString(),
    campaign: schedule.campaign,
    closedAt: "P04",
    scheduledSlots: slots.length,
    trialLaunches: runSlots.length,
    unrunSlots: unrunSlots.map((slot) => ({
        slot: slot.slot,
        pairId: slot.pairId,
        stamp: slot.stamp,
        scenario: slot.scenario,
        arm: slot.arm,
    })),
    judgeAttempts: {
        "attempt-001": {
            attempts: failedJudge.attempts,
            reachedModel: false,
            steps: failedJudge.steps,
            inputTokens: failedJudge.input,
            outputTokens: failedJudge.output,
            disposition: "auth failure, preserved, not a judgement",
        },
        "attempt-002": {
            attempts: judgeUsage.steps > 0 ? runSlots.length : 0,
            reachedModel: true,
            steps: judgeUsage.steps,
            inputTokens: judgeUsage.input,
            outputTokens: judgeUsage.output,
            reasoningTokens: judgeUsage.reasoning,
            cacheReadTokens: judgeUsage.cacheRead,
            successfulJudgements,
            disposition: "one judgement per run trial, preserved",
        },
    },
    successfulJudgements,
    blindJudgeAttemptsReachingModel: 8,
    trialUsage,
    judgeUsage,
    billing: {
        currency: "USD",
        trial: {
            model: "opencode-go/deepseek-v4.1-flash",
            basis: "catalogue rates 0.15 input / 0.60 output per Mtok, 0.003 cache-read",
            estimated: Number(trialEstimate.toFixed(4)),
            kind: "estimate from recorded tokens; no invoice",
        },
        judge: {
            model: "zai-coding-plan/glm-5.3-flash",
            basis: "coding-plan subscription; catalogue rates 0.0334 input / 0.1163 output per Mtok shown for scale",
            estimated: Number(judgeEstimate.toFixed(4)),
            kind: "plan credits, not a separate invoice; estimate descriptive only",
        },
        failedAuthAttempts: {
            tokens: 0,
            estimated: 0,
            note: "auth rejected before inference; no model tokens recorded",
        },
        actualInvoice: "unknown/not available",
    },
    preserved: {
        firstAttempts: "ac/attempt-001 on every run trial",
        recoveryJudgements: "ac/attempt-002 on every run trial",
        unrunSlots: "no result directories",
    },
};
write(
    join(EVIDENCE, "RECONCILIATION.json"),
    `${JSON.stringify(reconciliation, null, 2)}\n`,
);

// ---------------------------------------------------------------- human packets
const mulberry32 = (seed) => {
    let state = seed >>> 0;
    return () => {
        state = (state + 0x6d2b79f5) >>> 0;
        let t = state;
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
};
const seed = 20261111;
const random = mulberry32(seed);
const affected = runSlots.filter(
    (slot) =>
        measurement.retrievalOpportunities.includes(slot.scenario) &&
        ["S02", "R02"].includes(slot.scenario),
);
const shuffled = [...affected];
for (let index = shuffled.length - 1; index > 0; index -= 1) {
    const swap = Math.floor(random() * (index + 1));
    [shuffled[index], shuffled[swap]] = [shuffled[swap], shuffled[index]];
}
const map = shuffled.map((slot, index) => ({
    packet: `HR-${String(index + 1).padStart(2, "0")}`,
    stamp: slot.stamp,
    scenario: slot.scenario,
    arm: slot.arm,
}));
const packetDir = join(EVIDENCE, "human-review/packets");
mkdirSync(packetDir, { recursive: true });
const scrub = (text) =>
    text
        .replace(/\/home\/mark\/[^\s`)]+/g, "<host-path>")
        .replace(/\bses_[A-Za-z0-9]+/g, "<session>")
        .replace(/\bmsg_[A-Za-z0-9]+/g, "<message>")
        .replace(/\bcall_[A-Za-z0-9]+/g, "<call>")
        .replace(/\bp[df]-[AB]-r\d-[A-Z0-9]+/g, "<stamp>")
        .replace(/\battempt-\d{3}\b/g, "<attempt>");

const operationsOf = (slot) => {
    const dir = caseDir(slot);
    const lines = readText(join(dir, "docs-operations.jsonl"))
        .split("\n")
        .filter((line) => line.trim() !== "");
    return lines.map((line) => {
        const entry = JSON.parse(line);
        const input = entry.input ?? {};
        const target = input.read ?? input.add?.path ?? "";
        const verb = input.add
            ? `${input.add.mode ?? "write"} ${target}`
            : input.read
              ? `read ${target}`
              : input.search
                ? `search "${input.search}"`
                : input.check
                  ? "check"
                  : "help";
        return `- ${entry.surface ?? "native"} — ${entry.status ?? "unknown"} — ${verb}`;
    });
};

const notePaths = (slot) => {
    const before = join(ROOT, "gen", slot.arm.toLowerCase(), "fixtures", slot.scenario, "lakes");
    const paths = [];
    const walk = (dir, lake, relative) => {
        if (!existsSync(dir)) return;
        for (const entry of readdirSync(dir, { withFileTypes: true })) {
            const path = join(dir, entry.name);
            if (entry.isDirectory()) {
                walk(path, lake, `${relative}${entry.name}/`);
            } else if (entry.name.endsWith(".md")) {
                paths.push(`${lake}/${relative}${entry.name}`);
            }
        }
    };
    for (const lake of ["docs", "shared", "vendor"]) {
        walk(join(before, lake), lake, "");
    }
    return paths.sort();
};

const lakeOf = (slot, notePath) => {
    const root = join(
        ROOT,
        "gen",
        slot.arm.toLowerCase(),
        "fixtures",
        slot.scenario,
        "lakes",
    );
    return ["docs", "shared", "vendor"].find((lake) =>
        existsSync(join(root, lake, notePath)),
    );
};

const noteFor = (slot, notePath) => {
    const lake = lakeOf(slot, notePath);
    const before = readText(
        join(ROOT, "gen", slot.arm.toLowerCase(), "fixtures", slot.scenario, "lakes", lake, notePath),
    );
    const after = readText(join(caseDir(slot), "live/lakes", lake, notePath));
    return { before, after, qualified: `${lake}/${notePath}` };
};

const criterion = (scenario) => {
    const declaration = measurement.scenarios[scenario].retrieval;
    return `Target note: \`${declaration.note}\`\n\nSeeded detail: ${declaration.detail}\n\nThe original criterion: the note must be obtained through an attributable docs operation **and** its detail applied to the primary task. A correct answer alone proves neither.`;
};

let packetMarkdown = "";
for (const entry of map) {
    const slot = affected.find((one) => one.stamp === entry.stamp);
    const dir = caseDir(slot);
    const primary = readJson(join(dir, "primary-check.json"));
    const answer = scrub(readText(join(dir, "final.md")));
    const writes = scrub(readText(join(dir, "writes.txt")));
    const notePath = measurement.scenarios[slot.scenario].retrieval.note;
    const note = noteFor(slot, notePath);
    const otherNotes = notePaths(slot).filter(
        (path) => path !== note.qualified,
    );
    const body = `# Human review packet ${entry.packet}

This packet is arm-blind. Do not infer the arm from an answer style; assess
only the evidence below.

## Task

${scrub(readText(join(dir, "prompt.md")))}

## Retrieval criterion

${criterion(slot.scenario)}

## Seeded note before the trial (\`${notePath}\`)

\`\`\`
${scrub(note.before)}
\`\`\`

## Note after the trial

\`\`\`
${scrub(note.after)}
\`\`\`

## Other seeded notes (unchanged reference)

${otherNotes.map((path) => `- \`${path}\``).join("\n") || "- (none)"}

## Attributed docs operations

${operationsOf(slot).join("\n") || "- (none)"}

## Paths changed by the trial

\`\`\`
${writes.trim() || "(none)"}
\`\`\`

## Independent primary-task check

- status: ${primary.status}
- exit: ${String(primary.exit)}

## Final answer

\`\`\`
${answer.trim()}
\`\`\`

## Review questions

1. **Read attributable?** Is there a completed docs operation that reads the
   target note? (yes / no / unknown)
2. **Application?** Did the work apply the seeded detail to the primary task?
   Use the note's detail, the changed paths and the final answer. (applied /
   read-not-applied / search-only / not-retrieved / unknown)
3. **Evidence quote.** Quote the line that connects the retrieved detail to
   the work, or write "(none)".
4. **Confidence.** high / medium / low.
5. **Notes.**

Record the answers in \`../HUMAN-ASSESSMENT.json\`, not in this packet.
`;
    write(join(packetDir, `${entry.packet}.md`), body);
    packetMarkdown += `- ${entry.packet}: ${sha(body).slice(0, 16)}… (${body.length} chars)\n`;
}

write(
    join(EVIDENCE, "human-review/MAPPING.json"),
    `${JSON.stringify(
        {
            note: "Open only after every packet has been assessed; this is the arm mapping.",
            seed,
            packets: map,
            judgeOutputsPreserved: "ac/attempt-001 and ac/attempt-002 in each trial directory",
        },
        null,
        2,
    )}\n`,
);
write(
    join(EVIDENCE, "human-review/HUMAN-ASSESSMENT.json"),
    `${JSON.stringify(
        {
            status: "not-reviewed",
            criterion:
                "attributable docs read AND correct application to the primary task",
            derivedResult: true,
            note: "This file is a separate derived result. It never replaces the recorded judge outputs.",
            packets: map.map((entry) => ({
                packet: entry.packet,
                readAttributable: null,
                application: null,
                evidenceQuote: null,
                confidence: null,
                notes: null,
                reviewer: null,
                reviewedAt: null,
            })),
        },
        null,
        2,
    )}\n`,
);
write(
    join(EVIDENCE, "human-review/README.md"),
    `# Human review of the four affected retrieval opportunities

Four arm-blinded packets are in \`packets/\`. They are shuffled with seed
${seed}; the mapping is in \`MAPPING.json\` and must stay closed until every
assessment is recorded.

Fill \`HUMAN-ASSESSMENT.json\` and keep it separate from the original judge
outputs. It is a derived result, not a replacement judgement.

Packets (SHA-256 prefixes):

${packetMarkdown}
`,
);

if (!readText(LEDGER).includes('"campaign-closed"')) {
ledger({
    event: "campaign-closed",
    closedAt: "P04",
    reason: "retrieval assessment input was never captured for S02 and R02; no further model calls",
});
for (const slot of unrunSlots) {
    ledger({
        event: "slot-unrun",
        slot: slot.slot,
        pairId: slot.pairId,
        stamp: slot.stamp,
        scenario: slot.scenario,
        arm: slot.arm,
        reason: "campaign closed before launch",
    });
}
ledger({
    event: "human-review-packets",
    packets: map.length,
    seed,
    mapping: "evidence/human-review/MAPPING.json",
});

}
console.log(JSON.stringify(reconciliation, null, 2));

files.runner-regression.mjs:
// Focused runner regressions with temporary roots and stub launchers.
//
// 1. A closed ledger prevents run.mjs and rejudge.mjs from writing launch
//    events or invoking a child.
// 2. A preserved recovery attempt with a non-judged status blocks; a judged
//    attempt resumes without a duplicate call.
// 3. A non-executable logging shim stops the live path before the first launch.
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import {
    chmodSync,
    existsSync,
    mkdirSync,
    mkdtempSync,
    readFileSync,
    rmSync,
    writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";

const PREPARE = new URL(".", import.meta.url).pathname;
const STUB_COUNTER = "STUB_COUNTER";
const results = {};

const write = (path, body) => {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, body, "utf8");
};
const json = (path, value) => write(path, `${JSON.stringify(value, null, 2)}\n`);
const temp = (label) => mkdtempSync(join(tmpdir(), `pd-runner-${label}-`));

/** A schedule and the minimum files the commands read before a launch. */
const campaign = (label) => {
    const root = temp(label);
    write(
        join(root, "evidence/schedule.json"),
        JSON.stringify({
            campaign: `runner-${label}`,
            slots: [
                {
                    slot: 1,
                    pairId: "P01",
                    repetition: 0,
                    scenario: "X",
                    arm: "A",
                    stamp: "pd-A-r0-X",
                },
            ],
        }),
    );
    write(join(root, "evidence/ATTEMPTS.jsonl"), "");
    mkdirSync(join(root, "prepare/shim"), { recursive: true });
    write(join(root, "prepare/shim/podman"), "#!/usr/bin/env sh\nexit 0\n");
    chmodSync(join(root, "prepare/shim/podman"), 0o755);
    // If a broken guard reaches the child, this records it.
    write(
        join(root, "measurement/tests/fixtures/placement-harness/ac/run.mjs"),
        `import { appendFileSync } from "node:fs";\nappendFileSync(process.env.STUB_COUNTER, "judge\\n");\n`,
    );
    return root;
};

const counter = (root) => {
    const path = join(root, "counter.txt");
    return existsSync(path) ? readFileSync(path, "utf8") : "";
};

const run = (root, script, args, env = {}) =>
    spawnSync(process.execPath, [join(PREPARE, script), ...args], {
        env: { ...process.env, CAMPAIGN_ROOT: root, ...env },
        encoding: "utf8",
        timeout: 60000,
    });

// 1. Closed campaign: neither command writes or launches.
{
    const root = campaign("closed");
    const ledger = join(root, "evidence/ATTEMPTS.jsonl");
    const before = readFileSync(ledger, "utf8");
    write(
        ledger,
        `${before}${JSON.stringify({ event: "campaign-closed", at: "2026-11-11T00:00:00Z" })}\n`,
    );
    const closedBytes = readFileSync(ledger, "utf8");
    const stub = join(root, "trial-stub.sh");
    write(stub, `#!/usr/bin/env sh\nprintf 'trial\\n' >>"\${STUB_COUNTER}"\n`);
    chmodSync(stub, 0o755);
    const trial = run(
        root,
        "run.mjs",
        ["--pair-from", "1", "--pair-to", "1", "--trial-command", stub],
        { [STUB_COUNTER]: join(root, "counter.txt") },
    );
    const recovery = run(root, "rejudge.mjs", [], {
        [STUB_COUNTER]: join(root, "counter.txt"),
        ZAI_API_KEY: "stub",
    });
    assert.notEqual(trial.status, 0);
    assert.notEqual(recovery.status, 0);
    assert.equal(readFileSync(ledger, "utf8"), closedBytes);
    assert.equal(counter(root), "");
    results.closedCampaign = {
        trialExit: trial.status,
        recoveryExit: recovery.status,
        ledgerUnchanged: true,
        launcherCalls: 0,
    };
    rmSync(root, { recursive: true, force: true });
}

// 2. Preserved recovery attempts: failed blocks, judged resumes.
{
    const root = campaign("recovery");
    const caseDir = join(root, "gen/a/results/pd-A-r0-X/X");
    json(join(caseDir, "meta.json"), {
        exit: 0,
        signal: null,
        answerValid: true,
    });
    json(join(caseDir, "ac/attempt-002/judgement.json"), {
        status: "failed",
    });
    const failed = run(root, "rejudge.mjs", [], {
        [STUB_COUNTER]: join(root, "counter.txt"),
        ZAI_API_KEY: "stub",
    });
    const ledgerAfterFailure = readFileSync(
        join(root, "evidence/ATTEMPTS.jsonl"),
        "utf8",
    );
    assert.notEqual(failed.status, 0);
    assert.equal(counter(root), "");
    assert.ok(!ledgerAfterFailure.includes('"event":"recovery-complete"'));

    json(join(caseDir, "ac/attempt-002/judgement.json"), {
        status: "judged",
        documentationOutcome: "none",
        documentationReason: "preserved",
        evidence: ["preserved"],
    });
    const judged = run(root, "rejudge.mjs", [], {
        [STUB_COUNTER]: join(root, "counter.txt"),
        ZAI_API_KEY: "stub",
    });
    assert.equal(judged.status, 0);
    assert.equal(counter(root), "");
    assert.ok(
        readFileSync(join(root, "evidence/ATTEMPTS.jsonl"), "utf8").includes(
            '"event":"recovery-complete"',
        ),
    );
    results.recovery = {
        failedExit: failed.status,
        failedLauncherCalls: 0,
        judgedExit: judged.status,
        judgedLauncherCalls: 0,
    };
    rmSync(root, { recursive: true, force: true });
}

// 3. A non-executable shim stops the live path before launch.
{
    const root = campaign("shim");
    const shim = join(root, "prepare/shim/podman");
    chmodSync(shim, 0o644);
    const stub = join(root, "trial-stub.sh");
    write(stub, `#!/usr/bin/env sh\nprintf 'trial\\n' >>"\${STUB_COUNTER}"\n`);
    chmodSync(stub, 0o755);
    const trial = run(
        root,
        "run.mjs",
        ["--pair-from", "1", "--pair-to", "1", "--trial-command", stub],
        { [STUB_COUNTER]: join(root, "counter.txt") },
    );
    assert.notEqual(trial.status, 0);
    assert.equal(counter(root), "");
    assert.equal(
        readFileSync(join(root, "evidence/ATTEMPTS.jsonl"), "utf8"),
        "",
    );
    results.shim = {
        exit: trial.status,
        launcherCalls: 0,
        ledgerUnchanged: true,
    };
    rmSync(root, { recursive: true, force: true });
}

write(
    join(PREPARE, "RUNNER-REGRESSIONS.json"),
    `${JSON.stringify(results, null, 2)}\n`,
);
console.log(JSON.stringify(results, null, 2));

